begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor_id uuid,alert_id uuid,second_id uuid);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid());
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision alerts rollback fixture'from fixture union all select other_property,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision other alerts rollback fixture'from fixture;
create function pg_temp.fail_alert_event()returns trigger language plpgsql as $$begin if new.action like 'market.alert.%'and current_setting('p11.fixture.fail_alert',true)='yes'then raise exception 'Injected alert history failure';end if;return new;end$$;
create trigger fixture_alert_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_alert_event();
do $$declare f fixture;input jsonb;decision jsonb;r jsonb;before_count integer;did uuid:=gen_random_uuid();dismiss_id uuid:=gen_random_uuid();begin select *into f from fixture;
 input:='{"title":"Reported price discrepancy","description":"Operator notes require source review","severity":"warning","competitorId":null,"reason":"Flag exact reported discrepancy"}';
 perform pg_temp.check(not has_table_privilege('authenticated','public.market_alerts','select')and not has_table_privilege('authenticated','public.market_alerts','update')and not has_function_privilege('authenticated','public.review_marketvision_alerts(uuid,uuid,uuid,jsonb)','execute'),'direct browser writes and privileged RPC execution revoked');
 perform pg_temp.check(public.create_marketvision_alert(f.alert_id,f.property_id,gen_random_uuid(),input)->>'state'='forbidden','create requires current actor access');
 perform pg_temp.check(public.create_marketvision_alert(f.alert_id,f.property_id,f.actor_id,input||jsonb_build_object('competitorId',gen_random_uuid()))->>'state'='not_found','reported competitor must belong to property');
 begin perform public.create_marketvision_alert(f.alert_id,f.property_id,f.actor_id,input||'{"data":{"providerVerified":true}}');raise exception 'MISSING forged evidence';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Review the reported alert details','operator cannot forge provider data');end;
 perform set_config('p11.fixture.fail_alert','yes',true);begin perform public.create_marketvision_alert(f.alert_id,f.property_id,f.actor_id,input);raise exception 'MISSING atomic create';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Injected alert history failure','create surfaces history failure');end;perform set_config('p11.fixture.fail_alert','no',true);
 perform pg_temp.check(not exists(select 1 from public.market_alerts where id=f.alert_id),'failed recorded create leaves no alert');
 r:=public.create_marketvision_alert(f.alert_id,f.property_id,f.actor_id,input);perform pg_temp.check(r->>'state'='saved'and r->>'changed'='1','operator report is saved atomically');
 perform pg_temp.check(public.create_marketvision_alert(f.alert_id,f.property_id,f.actor_id,input)->>'state'='replayed'and(select count(*)=1 from public.market_alerts where property_id=f.property_id),'lost create response returns original report');
 perform pg_temp.check(public.create_marketvision_alert(f.alert_id,f.property_id,f.actor_id,input||'{"title":"Changed title"}')->>'state'='request_conflict','request cannot replace original reported evidence');
 perform public.create_marketvision_alert(f.second_id,f.property_id,f.actor_id,input||'{"title":"Another operator report"}');
 r:=public.read_marketvision_alerts(f.property_id,f.actor_id);perform pg_temp.check(r->'counts'->>'all'='2'and r->'counts'->>'unread'='2','complete counts come from the same read snapshot');
 perform pg_temp.check(r->'alerts'->0->>'source'='operator_reported'and not(r->'alerts'->0 ? 'data'),'source is reported and raw data is excluded');
 perform pg_temp.check(public.read_marketvision_alerts(f.property_id,gen_random_uuid())->>'state'='forbidden','read checks current membership');
 decision:=jsonb_build_object('action','read','reason','Reviewed exact displayed pair','alerts',jsonb_build_array(jsonb_build_object('id',f.alert_id,'expectedVersion',1),jsonb_build_object('id',f.second_id,'expectedVersion',1)));
 perform pg_temp.check(public.review_marketvision_alerts(did,f.other_property,f.actor_id,decision)->>'state'='not_found','review cannot cross properties');
 perform pg_temp.check(public.review_marketvision_alerts(did,f.property_id,f.actor_id,jsonb_set(decision,'{alerts,1,expectedVersion}','9'))->>'state'='stale_alert'and(select count(*)=0 from public.market_alerts where property_id=f.property_id and is_read),'one stale version prevents every selected update');
 begin perform public.review_marketvision_alerts(did,f.property_id,f.actor_id,jsonb_set(decision,'{alerts}',jsonb_build_array(decision->'alerts'->0,decision->'alerts'->0)));raise exception 'MISSING duplicates';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Review one to 50 unique displayed alerts','duplicate selection rejected');end;
 begin perform public.review_marketvision_alerts(did,f.property_id,f.actor_id,decision||'{"action":"read_all"}');raise exception 'MISSING hidden bulk';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Choose read, dismiss or restore','property-wide hidden selection retired');end;
 perform set_config('p11.fixture.fail_alert','yes',true);begin perform public.review_marketvision_alerts(did,f.property_id,f.actor_id,decision);raise exception 'MISSING atomic review';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Injected alert history failure','review surfaces history failure');end;perform set_config('p11.fixture.fail_alert','no',true);
 perform pg_temp.check((select count(*)=2 from public.market_alerts where property_id=f.property_id and version=1 and not is_read)and not exists(select 1 from public.marketvision_decisions where id=did),'all state versions and receipts roll back with history failure');
 r:=public.review_marketvision_alerts(did,f.property_id,f.actor_id,decision);perform pg_temp.check(r->>'state'='saved'and r->>'changed'='2','exact visible selection reviewed');
 perform pg_temp.check((select count(*)=2 from public.market_alerts where property_id=f.property_id and version=2 and is_read and read_at is not null),'each acknowledged alert records actual review time and version');
 perform pg_temp.check(public.review_marketvision_alerts(did,f.property_id,f.actor_id,decision)->>'state'='replayed','lost review reply replays without another write');
 perform pg_temp.check((select jsonb_array_length(d.before_state->'alerts')=2 and d.input=decision from public.marketvision_decisions d where d.id=did)and(select actor_id=f.actor_id and action='market.alert.read'from public.shared_action_events where id=did),'exact reviewed input and before/after states accompany actor evidence');
 perform pg_temp.check(public.review_marketvision_alerts(gen_random_uuid(),f.property_id,f.actor_id,decision)->>'state'='stale_alert','concurrent old-version review cannot reapply');
 decision:=jsonb_build_object('action','dismiss','reason','Dismiss the reviewed duplicate prompt','alerts',jsonb_build_array(jsonb_build_object('id',f.alert_id,'expectedVersion',2)));
 perform pg_temp.check(public.review_marketvision_alerts(dismiss_id,f.property_id,f.actor_id,decision)->>'state'='saved','dismissal records explicit reason');
 perform pg_temp.check(public.read_marketvision_alerts(f.property_id,f.actor_id,'dismissed')->'counts'->>'dismissed'='1'and jsonb_array_length(public.read_marketvision_alerts(f.property_id,f.actor_id,'open')->'alerts')=1,'dismissed records remain available outside the open view');
 perform pg_temp.check(public.review_marketvision_alerts(gen_random_uuid(),f.property_id,f.actor_id,jsonb_set(decision,'{alerts,0,expectedVersion}','3'))->>'state'='alert_state_changed','repeated dismissal is not a new successful outcome');
 decision:=jsonb_set(jsonb_set(decision,'{action}','"restore"'),'{alerts,0,expectedVersion}','3');perform pg_temp.check(public.review_marketvision_alerts(gen_random_uuid(),f.property_id,f.actor_id,decision)->>'state'='saved','restoration is separately recorded');
 perform pg_temp.check((select version=4 and is_read and not is_dismissed from public.market_alerts where id=f.alert_id),'restoration preserves original read evidence');
 perform pg_temp.check(public.read_marketvision_alerts(f.other_property,f.actor_id,'all',f.alert_id)->>'state'='cursor_changed','cursor cannot cross properties');
end$$;
insert into public.market_alerts(id,property_id,alert_type,title,description,data,created_at,is_read,is_dismissed,severity)select md5('alert-history-'||n)::uuid,f.property_id,'competitor_update','Earlier alert '||n,'Historical description','{"privateReceipt":"must not return"}'::jsonb,case when n=1003 then null else '2020-01-01'::timestamptz end,null,null,null from fixture f cross join generate_series(1,1003)n;
do $$declare f fixture;cursor_id uuid;page jsonb;ids uuid[]:='{}';begin select *into f from fixture;loop page:=public.read_marketvision_alerts(f.property_id,f.actor_id,'all',cursor_id,50);select ids||array_agg((value->>'id')::uuid)into ids from jsonb_array_elements(page->'alerts');cursor_id:=(page->>'nextCursor')::uuid;exit when cursor_id is null;end loop;perform pg_temp.check(array_length(ids,1)=1005 and(select count(distinct id)=1005 from unnest(ids)id),'all 1005 alerts page exactly once through tied and missing dates');perform pg_temp.check((page->'counts'->>'all')::integer=1005 and(page->'counts'->>'unread')::integer=1003,'complete counts exceed default row cap and do not invent acknowledgments');perform pg_temp.check(page::text not like '%privateReceipt%'and page->'alerts'->(jsonb_array_length(page->'alerts')-1)->'createdAt'='null'::jsonb,'unknown dates remain unknown and private legacy receipts are omitted');end$$;
select count(*)as passed_alert_assertions from checks;
rollback;
